    """Returns the sum of the positive divisors of |x|, with 0 mapped to 2."""
    n = x if x >= 0 else -x
    if n == 0:
        return 2
    s = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            s += i
            j = n // i
            if j != i:
                s += j
        i += 1
    return s

